// Laser File: bytes -> frame v2 (laser Phase 9). Fixtures are generated by these tests (ILDA via
// writeIlda) or written here by hand (SVG) — none comes from outside the repo.
import { describe, expect, it } from 'vitest'
import { FRAME_MAX_POINTS, flattenLaserPaths, normaliseLaserPaths } from '../../../shared/laserFrame.js'
import { createNode } from '../../nodeRegistry.js'
import { createNodeGraphContext, evaluateNodeOutput } from '../../graph/nodeGraphRuntime.js'
import { capPaths } from './capPaths.js'
import { writeIlda } from './ildaFile.js'
import { readLaserFile, svgPaths } from './laserFile.js'

const enc = (s) => new TextEncoder().encode(s)
const vertices = (frame) => frame.paths.reduce((s, p) => s + p.p.length / 5, 0)
const inField = (frame) => frame.paths.every((p) => p.p.every((v, i) => (i % 5 < 2 ? v >= -1 && v <= 1 : v >= 0 && v <= 1)))
const circlePath = (n, r = 0.5) => {
    const p = []
    for (let i = 0; i < n; i += 1) p.push(r * Math.cos((2 * Math.PI * i) / n), r * Math.sin((2 * Math.PI * i) / n), 0, 1, 0)
    return { p, closed: true }
}

describe('Laser File tells ILDA from SVG by the bytes', () => {
    it('an ILDA file gives its frame, kept in the artist\'s order, as clean frame v2', () => {
        const read = readLaserFile(writeIlda([{ paths: [circlePath(40)] }], { format: 5 }))
        expect(read).toMatchObject({ ok: true, kind: 'ilda', frames: 1 })
        expect(read.frame).toMatchObject({ kind: 'laser', v: 2, order: 'kept' })
        expect(read.frame.paths).toHaveLength(1)
        expect(read.frame.paths[0].closed).toBe(true)
        expect(vertices(read.frame)).toBe(40)
        expect(normaliseLaserPaths(read.frame).paths).toHaveLength(1)
        expect(read.status).toMatch(/^ILDA format 5, frame 1 of 1, 1 paths, 40 points$/)
    })

    it('an SVG document gives every <path>, fitted to 80 % of the field, y up, with its stroke colour', () => {
        const svg = '<svg xmlns="http://www.w3.org/2000/svg"><path d="M0 0 L100 0" stroke="#ff0000"/><path style="fill:none;stroke:#0000ff" d="M0 0 L0 50"/></svg>'
        const read = readLaserFile(enc(svg))
        expect(read).toMatchObject({ ok: true, kind: 'svg' })
        const [a, b] = read.frame.paths
        expect(a.p.map((v) => Math.round(v * 1e6) / 1e6)).toEqual([-0.8, 0.4, 1, 0, 0, 0.8, 0.4, 1, 0, 0])
        // SVG y runs down: the line to (0, 50) goes DOWN the field
        expect(b.p[1]).toBeGreaterThan(b.p[6])
        expect(b.p.slice(2, 5)).toEqual([0, 0, 1])
    })

    it('bare path data (no markup) is read as one path', () => {
        const read = readLaserFile('M 0 0 L 10 10 Z')
        expect(read.ok).toBe(true)
        expect(read.frame.paths).toHaveLength(1)
        expect(read.frame.paths[0].closed).toBe(true)
    })

    it('a stated tolerance in field units: a finer one takes more chords on an SVG circle', () => {
        const svg = '<svg><path d="M0 50 A 50 50 0 1 0 100 50 A 50 50 0 1 0 0 50"/></svg>'
        const coarse = readLaserFile(enc(svg), { tolerance: 0.02 })
        const fine = readLaserFile(enc(svg), { tolerance: 0.0005 })
        expect(vertices(fine.frame)).toBeGreaterThan(vertices(coarse.frame))
        // the arcs' bulge is inside the bounds: nothing reaches the field's edge (fitted to 0.8)
        for (const r of [coarse, fine]) for (const p of r.frame.paths) for (let i = 0; i < p.p.length; i += 5) expect(Math.hypot(p.p[i], p.p[i + 1])).toBeLessThanOrEqual(0.8 + 1e-3)
    })

    it('colour wired recolours every point; level dims; size and height move it', () => {
        const bytes = writeIlda([{ paths: [{ p: [0.5, 0.5, 1, 1, 1, -0.5, 0.5, 1, 1, 1], closed: false }] }], { format: 4 })
        const read = readLaserFile(bytes, { colour: '#00ff00', level: 0.5, size: 0.5, height: 0.25 })
        const p = read.frame.paths[0].p.map((v) => Math.round(v * 1e4) / 1e4)
        expect(p).toEqual([0.25, 0.5, 0, 0.5, 0, -0.25, 0.5, 0, 0.5, 0])
    })

    it('an ILDA file with several frames: index picks one and wraps both ways', () => {
        const frames = [0.1, 0.2, 0.3].map((x) => ({ paths: [{ p: [x, 0, 1, 0, 0, x, 0.5, 1, 0, 0], closed: false }] }))
        const bytes = writeIlda(frames, { format: 1 })
        const xAt = (index) => Math.round(readLaserFile(bytes, { index }).frame.paths[0].p[0] * 1000) / 1000
        expect([xAt(0), xAt(1), xAt(2), xAt(3), xAt(-1)]).toEqual([0.1, 0.2, 0.3, 0.1, 0.3])
    })

    it('lists what an SVG holds that it does not read', () => {
        expect(svgPaths('<svg><g transform="scale(2)"><path d="M0 0L1 1" transform="rotate(4)"/></g><rect/><circle/></svg>'))
            .toMatchObject({ skipped: 2, transforms: 2 })
    })
})

describe('Laser File caps (FRAME_MAX_POINTS)', () => {
    it(`an ILDA frame of 6000 points comes out within ${FRAME_MAX_POINTS} vertices, the cut counted`, () => {
        const read = readLaserFile(writeIlda([{ paths: [circlePath(6000)] }], { format: 5 }))
        expect(vertices(read.frame)).toBeLessThanOrEqual(FRAME_MAX_POINTS)
        expect(read.cut.points).toBe(6000 - vertices(read.frame))
        expect(read.status).toMatch(/cut \d+ points/)
        // and Laser Out's flatten of it fits the wire
        expect(flattenLaserPaths(read.frame, { budget: 'auto' }).points.length).toBeLessThanOrEqual(FRAME_MAX_POINTS)
    })

    it(`an SVG of 1500 separate lines (3000 vertices) keeps ${FRAME_MAX_POINTS / 2} of them, the longest, and counts the rest`, () => {
        const d = Array.from({ length: 1500 }, (_, i) => `M${i} 0 l0 ${1 + (i % 7)}`).join(' ')
        const read = readLaserFile(enc(`<svg><path d="${d}"/></svg>`))
        expect(vertices(read.frame)).toBeLessThanOrEqual(FRAME_MAX_POINTS)
        expect(read.frame.paths).toHaveLength(FRAME_MAX_POINTS / 2)
        expect(read.cut.paths).toBe(500)
        expect(inField(read.frame)).toBe(true)
    })

    it('capPaths keeps each path\'s ends and never passes the cap', () => {
        const big = { p: Array.from({ length: 3000 }, (_, i) => [i / 3000, 0, 1, 1, 1]).flat(), closed: false }
        const { paths, cutPoints } = capPaths([big, circlePath(10)], 100)
        expect(paths.reduce((s, p) => s + p.p.length / 5, 0)).toBeLessThanOrEqual(100)
        expect(paths[0].p.slice(0, 2)).toEqual([0, 0])
        expect(paths[0].p.slice(-5, -3)).toEqual([2999 / 3000, 0])
        expect(cutPoints).toBeGreaterThan(0)
    })
})

describe('Laser File refusals, each by name', () => {
    it.each([
        ['empty', new Uint8Array(0)],
        ['not-laser-file', enc('hello, not a drawing')],
        ['not-laser-file', new Uint8Array([0x89, 0x50, 0x4e, 0x47, 13, 10, 26, 10])],
        ['truncated-records', writeIlda([{ paths: [circlePath(10)] }], { format: 0 }).slice(0, 32 + 6 + 32 + 20)],
        ['no-paths', enc('<svg><rect width="3" height="3"/></svg>')],
        ['not-moveto', enc('<svg><path d="L 1 1"/></svg>')],
    ])('%s', (reason, bytes) => {
        const read = readLaserFile(bytes)
        expect(read.ok).toBe(false)
        expect(read.reason).toBe(reason)
        expect(read.status).toMatch(new RegExp(`^Refused: ${reason}`))
    })
})

describe('the laser.file node', () => {
    const run = (values, bytes, port = 'frame', now = 0) => {
        const node = createNode('laser.file', { id: 'lf', values })
        const liveOutputs = new Map(bytes ? [['lf:bytes', bytes]] : [])
        return evaluateNodeOutput(node, port, createNodeGraphContext({ nodes: [node], edges: [] }, { now, liveOutputs }))
    }
    it('says why it carries nothing: no file, then loading', () => {
        expect(run({}, null)).toBeUndefined()
        expect(run({}, null, 'status')).toBe('No file chosen')
        expect(run({ src: 'a1' }, null, 'status')).toBe('Loading the file')
    })
    it('reads the bytes the editor published and plays an ILDA file at Speed frames a second', () => {
        const bytes = writeIlda([0.1, 0.2, 0.3].map((x) => ({ paths: [{ p: [x, 0, 1, 0, 0, x, 0.5, 1, 0, 0], closed: false }] })), { format: 5 })
        expect(run({ src: 'a1' }, bytes, 'frames')).toBe(3)
        const x = (now) => Math.round(run({ src: 'a1', fps: 2 }, bytes, 'frame', now).paths[0].p[0] * 10) / 10
        expect([x(0), x(500), x(1000), x(1500)]).toEqual([0.1, 0.2, 0.3, 0.1])
    })
    it('a refused file shows its reason on Status and carries nothing', () => {
        expect(run({ src: 'a1' }, enc('nope'))).toBeUndefined()
        expect(run({ src: 'a1' }, enc('nope'), 'status')).toMatch(/^Refused: not-laser-file/)
    })
})

// Review of PR #1071, finding 1: size and height used to press what leaves the field onto its edge.
describe('Laser File blanks what leaves the field', () => {
    const corners = (frame) => {
        let c = 0
        for (const path of frame.paths) for (let i = 0; i < path.p.length; i += 5) if (Math.abs(path.p[i]) === 1 && Math.abs(path.p[i + 1]) === 1) c += 1
        return c
    }
    it('an ILDA circle at Size 10 draws its arcs inside the field, not a square on its edge', () => {
        const read = readLaserFile(writeIlda([{ paths: [circlePath(400, 0.8)] }], { format: 5 }), { size: 10 })
        expect(read.ok).toBe(true)
        expect(inField(read.frame)).toBe(true)
        expect(corners(read.frame)).toBe(0)
        // every vertex kept is on the circle (radius 8 now), so nothing runs along the edge
        for (const path of read.frame.paths) for (let i = 0; i < path.p.length; i += 5) {
            expect(Math.abs(Math.hypot(path.p[i], path.p[i + 1]) - 8)).toBeLessThan(0.01)
        }
        expect(read.outside).toBeGreaterThan(0)
        expect(read.status).toMatch(/points outside the field blanked/)
    })
    it('an SVG line moved past the top by Height draws nothing, not a line along y = 1', () => {
        const read = readLaserFile(enc('M0 0 L1 1'), { height: 9 })
        expect(read.ok).toBe(true)
        expect(read.frame.paths).toEqual([])
        expect(read.outside).toBe(2)
    })
})

// Review of PR #1071, finding 4: with Speed > 0 an SVG was flattened again at every frame step.
describe('the laser.file node reads an SVG once whatever the Speed', () => {
    it('gives the same frame object at every frame step', () => {
        const node = createNode('laser.file', { id: 'lf-svg', values: { src: 'a2', fps: 10 } })
        const bytes = enc('<svg><path d="M0 0 C 10 20 30 40 50 0"/></svg>')
        const liveOutputs = new Map([['lf-svg:bytes', bytes]])
        const at = (now) => evaluateNodeOutput(node, 'frame', createNodeGraphContext({ nodes: [node], edges: [] }, { now, liveOutputs }))
        const first = at(0)
        expect(first.paths.length).toBe(1)
        expect(at(100)).toBe(first)
        expect(at(2500)).toBe(first)
    })
})

// Review of PR #1071, finding 5: the cap rounded down, so one long path kept 1999 of 2000 vertices.
describe('capPaths fills the cap exactly', () => {
    it('one 20 000-vertex path keeps FRAME_MAX_POINTS, ends included', () => {
        const big = { p: [], closed: false }
        for (let i = 0; i < 20000; i += 1) big.p.push(-1 + (2 * i) / 19999, 0, 1, 1, 1)
        const out = capPaths([big])
        expect(out.paths[0].p.length / 5).toBe(FRAME_MAX_POINTS)
        expect(out.cutPoints).toBe(20000 - FRAME_MAX_POINTS)
        expect(out.paths[0].p.slice(0, 2)).toEqual([-1, 0])
        expect(out.paths[0].p.slice(-5, -3)).toEqual([1, 0])
    })
    it('three uneven paths sum to the cap, never past it', () => {
        const line = (n) => ({ p: Array.from({ length: n }, (_, i) => [i / n, 0, 1, 1, 1]).flat(), closed: false })
        const out = capPaths([line(7001), line(3333), line(999)], 1000)
        expect(out.paths.reduce((s, p) => s + p.p.length / 5, 0)).toBe(1000)
    })
})
